/*
## FilesWindow — a column browser over the repo's own documentation

Three columns — folders, files, and a preview — over a tree derived live from
the documentation model (`app.docsModel`), so nothing here goes stale when the
docs move. The window's title is the deepest open folder. The columns scroll
and clip independently, the dividers between them drag, and a double-click
opens a document in the Viewer.
*/

class FilesWindow extends Window [ forApp = "files",

    // the SELECTION CHAIN: the open nodes' names, newline-joined, one per column
    // ("" = nothing open). Every level of the hierarchy — even the top — is DATA
    // (app.docsModel.value.browse, the one documentation model); this window
    // chooses no categories of its own.

    selPath: string = "",
    rootPath: string = "",                       // the folder this window is ROOTED at ("" = the whole tree); a double-clicked folder opens a new window rooted at itself
    colW: number = 250,                          // default column width (fixed; drag a seam to resize)
    widths: number[] = [],                       // per-column width overrides by depth — Finder resizes ONE column
    rowH: number = 24,                           // one Finder row — icon + name, single line
    cw0: number = 0,                             // divider-drag anchors
    cpx0: number = 0,
    cwk: number = -1,                            // depth of the column being dragged
    pendingAt: string = "",                      // the item awaiting a possible second click (data-level double-click)
    pendingItem: object,                         // that item's record (name/path/doc/hasKids/at) — what a second click opens
    pendingPX: number = 0,                       // the pointer at the first click (root space) — a double-click is
    pendingPY: number = 0,                       //   time + POINTER distance, so a row sliding under the cursor

    //   (the strip's reveal scroll) can never retarget the second click

    focusDepth: number = -1,                     // >=0: open pinned to this column at the LEFT edge (a folder opened into a new window), ancestors scroll-left; -1: reveal the deepest column

    // the window's name is the deepest open node, or "Documentation"

    title = { this.selPath != "" ? (("" + this.selPath).split("\n").pop() ?? "Documentation") : (this.rootPath != "" ? (("" + this.rootPath).split("\n").pop() ?? "Documentation") : "Documentation") },

    // Walk `browse` along selPath into a flat list of columns: one LIST column
    // per level (its child nodes), then a DETAIL column once the deepest
    // selection is a leaf. Each item carries `at` — the exact selPath that opens
    // it — so a row's click is one assignment and truncation is automatic (the
    // list re-derives). Miller columns fall straight out of a recursive walk.

    columnData(selPath: string, model: object, rootPath: string) -> array {
        const rootParts = rootPath == "" ? [] : rootPath.split("\n")
        const parts = selPath == "" ? [] : selPath.split("\n")
        const item = (n, p) => ({ name: "" + n.name, kind: "" + (n.kind || ""), label: "" + (n.label || ""),
            hasKids: (n.children != null && n.children.length > 0),
            path: "" + (n.path || ""), doc: "" + (n.doc || ""), preview: "" + (n.preview || ""),
            at: p.join("\n") })
        let level = ((model || ({ })).browse) || []
        // descend to the window's ROOT folder — its children are the first column
        for (let i = 0; i < rootParts.length; i = i + 1) {
            const n = level.find((x) => x.name == rootParts[i])
            if (n == null || n.children == null) return []
            level = n.children
        }
        // the selPath BELOW the root drives the drill; `at` stays the absolute path
        const drill = parts.slice(rootParts.length)
        const cols = []
        cols.push(({ items: level.map((n) => item(n, rootParts.concat([n.name]))), depth: 0 }))
        for (let k = 0; k < drill.length; k = k + 1) {
            const chosen = level.find((n) => n.name == drill[k])
            if (chosen == null) break
            const prefix = rootParts.concat(drill.slice(0, k + 1))
            if (chosen.children != null && chosen.children.length > 0) {
                level = chosen.children
                cols.push(({ items: level.map((n) => item(n, prefix.concat([n.name]))), depth: cols.length }))
            } else {
                cols.push(({ leaf: item(chosen, prefix), depth: cols.length }))
                break
            }
        }
        return cols
        },
    cols: Dataset [ contents = { ({ list: classroot.columnData(classroot.selPath, app.docsModel.value, classroot.rootPath) }) } ],

    // open a leaf — every leaf is a document. An authored file (`path`) opens its
    // source; a hydrated page (`doc`, assembled by the model) opens whole. Same
    // Markdown window either way; the browser special-cases nothing.

    // `v` is the view the open CAME FROM — the row, the Open button — and it is
    // what the new window zooms out of. It used to pass `this`, which in a
    // classroot method is the whole FilesWindow, so opening a file zoomed out of
    // the middle of the browser rather than out of the file. The folder path
    // beside it always passed its row (`openFolderWindow(…, this)`), which is
    // why a folder looked right and a file did not.

    openLeaf(leaf: object, v: View?) {
        const d = "" + (leaf.doc || ""), p = "" + (leaf.path || "")
        if (d != "") { app.openDoc(d, "" + leaf.name, v); return }
        if (p != "") app.openViewer("../../" + p, "" + leaf.name, v)
        },

    // File → Open (⌘O) on this window's current selection: a document opens in the
    // viewer, a folder opens a new window rooted at it — the double-click actions.

    openSelection() {
        if (this.selPath == "") return
        const cols = this.columnData(this.selPath, app.docsModel.value, this.rootPath)
        const last = cols[cols.length - 1]
        if (last != null && last.leaf != null) this.openLeaf(last.leaf, null)
        else app.openFolderWindow("" + this.selPath, this)
        },

    body: View [ x = 0, y = { classroot.barH }, width = { parent.width }, height = { parent.height - classroot.barH },
        fill = { theme.bg },

        // the column STRIP: a horizontal row as wide as the open columns need,
        // inside a viewport that scrolls RIGHT (scrolls = x) as they accumulate — a
        // trackpad's horizontal delta drives it, and the runtime swallows that
        // gesture so it never becomes Safari's back-swipe (dom-backend setScrollX).

        strip: View [ x = 0, y = 0, width = { parent.width }, height = { parent.height }, scrolls = x,
            datapath = { classroot.cols.value },

            // the strip's own reveal: a column that finds itself occluded asks
            // the STRIP to glide to a new left position (`reveal.to` then
            // `start()`). The strip is the only thing that moves — this is
            // deliberately NOT scrollIntoView, which reveals on every axis
            // through every ancestor scroller: hosted in a short viewport (the
            // Viewer's edit preview), that walk scrolled the EMBEDDING island
            // vertically. The window's interior animating itself cannot.

            reveal: Animator [ attribute = scrollX, to = 0, duration = 260, motion = cubicOut ],
            row: View [ x = 0, y = 0, height = { parent.height },
                width = { (classroot.cols.value.list || []).reduce((s, c) => s + (classroot.widths[c.depth] != null ? classroot.widths[c.depth] : classroot.colW), 0) },
                layout: SimpleLayout [ axis = x, spacing = 0 ],

                // ONE column per browse level (its child nodes), then the final
                // leaf-DETAIL column once the deepest selection has no children.
                // Each column keeps its own width (Finder: drag one seam, one column).

                // keyed by DEPTH — the stable identity of a column. columnData mints
                // fresh records every derivation; unkeyed, a selection change rebuilt
                // every column (the row emptied for a frame, the native scroller
                // clamped to 0 — a visible left-pop before the reveal scrolled back).
                // Keyed, a selection updates columns in place: no churn, no pop, and
                // only a genuinely NEW (deeper) column runs its reveal.

                View [ datapath = :list[], key = :depth, height = { parent.height }, clip = true, fill = { theme.bg },
                    width = { classroot.widths[:depth] != null ? classroot.widths[:depth] : classroot.colW },

                    // a freshly-opened column reveals itself — IF the window's
                    // frame occludes it, the strip glides to a new left position,
                    // ANIMATED (not a pop). Occlusion is judged here, against the
                    // strip's own viewport, and only `strip.scrollX` moves: the
                    // reveal can never touch any other scroller, however this app
                    // is hosted. Deferred past the double-click window (400ms) so
                    // a second click still lands on the same, un-moved row. A
                    // window opened onto a folder (focusDepth >= 0) instead pins
                    // THAT column to the left edge, so its contents lead.

                    onInit() { setTimeout(() => {
                        const strip = classroot.body.strip
                        const fd = classroot.focusDepth
                        const left = this.x, right = left + this.width
                        let to = -1
                        if (fd < 0) {
                            if (right > strip.scrollX + strip.width) to = right - strip.width
                            else if (left < strip.scrollX) to = left
                        } else if (:depth == fd) to = left
                        if (to >= 0) {
                            // no clamp here: the scroll write is clamped by the
                            // platform to the strip's contained extent, exactly
                            // like a user scroll — the app states the intent
                            strip.reveal.to = to
                            strip.reveal.start()
                        }
                    }, 440) },

                    // a LIST column — this level's nodes as selectable rows

                    lst: View [ visible = { :items != null }, x = 0, y = 0, width = { parent.width }, height = { parent.height }, scrolls = y,

                        // a second click that lands on DEAD SPACE (the reveal slide moved
                        // the rows out from under the pointer) still completes a pointer-
                        // anchored double-click — rows don't bubble, so this fires only
                        // when no row took the hit

                        onClick() {
                            const near = Math.abs(app.pointerX - classroot.pendingPX) < 6 && Math.abs(app.pointerY - classroot.pendingPY) < 6
                            const it = classroot.pendingItem
                            if (classroot.pendingAt != "" && it != null && near) {
                                classroot.pendingAt = ""
                                if (it.hasKids) app.openFolderWindow("" + it.at, this)
                                else classroot.openLeaf(it, this)
                            }
                            },
                        inner: View [ x = 0, y = 6, width = { parent.width }, height = { this.contentHeight + 12 },
                            layout: SimpleLayout [ axis = y, spacing = 1 ],
                            View [ datapath = :items[], width = { parent.width }, height = { classroot.rowH },
                                on: boolean = { classroot.selPath != "" && (("" + classroot.selPath) + "\n").indexOf(("" + :at) + "\n") == 0 },
                                onClick() {
                                    classroot.activate()
                                    const at = "" + :at
                                    // data-level double-click, POINTER-anchored (the OS rule: two clicks
                                    // within a time window AND a few px of pointer travel — row identity
                                    // deliberately NOT consulted). The second click opens the PENDING item
                                    // even when the strip's reveal scroll has slid a different row under
                                    // the cursor; matching rows instead let a stray hit reselect an
                                    // ancestor and truncate the columns back toward the root, and would
                                    // pair two distant clicks through a row that slid between them.
                                    const near = Math.abs(app.pointerX - classroot.pendingPX) < 6 && Math.abs(app.pointerY - classroot.pendingPY) < 6
                                    const it = classroot.pendingItem
                                    if (classroot.pendingAt != "" && it != null && near) {
                                        classroot.pendingAt = ""
                                        if (it.hasKids) app.openFolderWindow("" + it.at, this)
                                        else classroot.openLeaf(it, this)
                                    }
                                    else {
                                        classroot.pendingAt = at
                                        classroot.pendingItem = ({ name: "" + :name, path: "" + :path, doc: "" + :doc, hasKids: !!:hasKids, at: at })
                                        classroot.pendingPX = app.pointerX
                                        classroot.pendingPY = app.pointerY
                                        classroot.selPath = at
                                        setTimeout(() => { if (classroot.pendingAt == at) classroot.pendingAt = "" }, 550)
                                    }
                                    },
                                hl: View [ x = 4, y = 2, width = { parent.width - 8 }, height = { classroot.rowH - 4 }, cornerRadius = 5,
                                    visible = { parent.on }, fill = { theme.accent } ],
                                fo: FolderIcon [ x = 11, y = center, visible = { :hasKids } ],
                                fi: FileIcon [ x = 12, y = center, visible = { !:hasKids } ],
                                nm: Text [ x = 34, y = center, fontSize = 13, wrap = false, width = { parent.width - 52 },
                                    textColor = { parent.on ? theme.accentText : theme.text }, text = { "" + :name } ],
                                chev: Text [ x = { parent.width - 15 }, y = center, fontSize = 12, visible = { :hasKids },
                                    textColor = { parent.on ? theme.accentText : theme.textFaint }, text = "›" ]
                                ]
                            ],
                        edge: View [ x = { parent.width - 1 }, y = 0, width = 1, height = { parent.height }, fill = { theme.line } ]
                        ],

                    // the LEAF DETAIL column — name, kind, a preview, and Open

                    det: View [ visible = { :leaf != null }, x = 18, y = 20, width = { parent.width - 36 },
                        layout: SimpleLayout [ axis = y, spacing = 11 ],
                        dn: Text [ fontSize = 14, fontWeight = semibold, wrap = true, width = { parent.width },
                            textColor = { theme.text }, text = { "" + :leaf.name } ],
                        dk: Text [ fontSize = 11, wrap = false, textColor = { theme.textFaint },
                            text = { "" + :leaf.label } ],
                        dp: Text [ fontSize = 12, wrap = true, width = { parent.width },
                            textColor = { theme.text }, text = { "" + :leaf.preview } ],
                        Button [ width = 92, label = "Open", primary = true, visible = { :leaf.path != "" || :leaf.doc != "" },
                            onClick() { classroot.openLeaf(:leaf, this) }
                            ]
                        ],

                    // drag any seam to resize the columns (fixed width, Finder-style)

                    grip: View [ x = { parent.width - 4 }, y = 0, width = 8, height = { parent.height }, cursor = "col-resize",
                        onPointerDown() { classroot.activateOnPress(); classroot.cwk = :depth; classroot.cw0 = parent.width; classroot.cpx0 = app.pointerX },
                        onPointerMove() { if (classroot.cwk == :depth) { const nw = Math.max(150, Math.min(460, classroot.cw0 + app.pointerX - classroot.cpx0)); const a = [...classroot.widths]; a[:depth] = nw; classroot.widths = a } },
                        onPointerUp() { classroot.cwk = -1 }
                        ]
                    ]
                ]
            ]
        ]
    ]


/*
## AppWindow — a whole Declare app inside a desktop window

The window frame around an `AppIsland` — the library's app-embedding primitive.
Give the island a `program` and it mounts that app as its own child: its own
reactive graph, input router, sized to the island's box. The path is relative,
so `"../../calendar/calendar"` reaches the real calendar app: no copy, no shim.
The window adds only what a window owns — the title (taken from the running
child's own name, `island.childName`), activation, and the `dark` + `extraEnv`
environment it hands the island.
*/

class AppWindow extends Window [ width = 880, height = 560,
    extraEnv: string = "",                       // appended env parameters ("program=…")

    // the window's name is the HOSTED app's name, reflected up from the embedded
    // child (`island.childName`): the viewer titles by the file it shows and
    // follows its navigation. `appTitle` is the fallback until the child is up.

    appTitle: string = "",
    title = { this.island.childName != "" ? this.island.childName : this.appTitle },

    // the slot's ENV segment (after `|`) is the embedding environment — the
    // host parses it into the child's reactive `app.env`, at mount and on
    // every change: toggling the desktop's appearance re-marks the slot and
    // the hosted app re-derives (its Auto mode follows `app.env.dark`)

    // a press anywhere in the hosted app also lands here (the router remaps
    // embedded presses to the island — dom-backend), so clicking the child's
    // content raises this window exactly as clicking any window body does

    island: AppIsland [ x = 0, y = { classroot.barH }, width = { parent.width }, height = { parent.height - classroot.barH },
        onPointerDown() { classroot.activateOnPress() },
        onClick()       { classroot.activate() },
        onHold()        { classroot.activate() },
        program = { classroot.appPath },

        // The TYPED half of the dark channel (islands design): a tenant that
        // declares `external darkMode: boolean` gets this as a checked fact,
        // handshake and all. `env.dark` below stays — the untyped ancestor —
        // so every existing tenant keeps working; new tenants should pair.

        external darkMode: boolean = { app.darkMode },
        env = { "dark=" + (app.darkMode ? "1" : "0")
            + (classroot.extraEnv != "" ? "&" + classroot.extraEnv : "") }
        ]
    ]


/*
## ViewerWindow — a Markdown window over a real document

Renders a document with the library's `Markdown` view. A `"ref:"` path builds a
reference page from the documentation model; anything else fetches the real
file as text. Its title is the file's basename.
*/

class ViewerWindow extends Window [ width = 640, height = 460, forApp = "markdown",
    path: string = "",

    // the window's name is the FILE being viewed — its basename, not the path
    // (a "ref:" page names the element). The same basename rule the standalone
    // viewer app titles itself by, so the two agree.

    // a viewer opens either a real FILE (a `path` it fetches) or a HYDRATED doc
    // handed over whole (`inlineDoc` — a page the model already assembled, e.g.
    // an element's reference). `docName` titles a hydrated doc; a file titles by
    // its basename.

    inlineDoc: string = "",
    docName: string = "",
    title = { this.inlineDoc != "" ? this.docName : (this.path.split("/").pop() || "") },

    src: DataSource [ format = "text", url = { classroot.path } ],

    // the scrolling body is a real pointer target covering the whole window,
    // and subclass children attach after the base's — so the Window's resize
    // strips re-promote above it (order is a slot) or edge drags never land

    onInit() {
        if (this.inlineDoc == "") this.src.fetch()
        this.raiseChrome()
        },

    body: View [ x = 0, y = { classroot.barH }, width = { parent.width }, height = { parent.height - classroot.barH },
        scrolls = y, selectable = true,

        // THE DOCS READING TREATMENT, carried over whole (docs.declare is the
        // reference): 48px side margins and 40 above (the pad's explicit height
        // adds the same 40 below, so the scroll extent ends with breathing room);
        // prose wraps at the 560 reading measure while code fills the column;
        // 1.6 leading; the docs body ink; and every code block gets the tinted
        // box with the teal left bar. The chip tints are the docs values on the
        // shared white surface, and a neutral step-up of the same relationship
        // on Cupertino's dark surface (the docs dark chip is tuned to its own
        // blue-black page, not to 0x2C2C2E).

        pad: View [ x = 48, y = 40, width = { parent.width - 96 },
            height = { this.doc.height + 40 },
            loading: Text [ fontSize = 13, textColor = { theme.textFaint },
                visible = { classroot.inlineDoc == "" && classroot.src.loading }, text = "Loading…" ],
            failed: Text [ fontSize = 13, textColor = { theme.textFaint }, wrap = true, width = { parent.width },
                visible = { classroot.inlineDoc == "" && classroot.src.failed },
                text = { "Could not load — " + (classroot.src.error || "") } ],
            doc: Markdown [ width = { parent.width },
                visible = { classroot.inlineDoc != "" || classroot.src.loaded },
                richTextLayout = { { default: { maxWidth: 560 }, code: { maxWidth: 0 } } },
                lineHeight = 1.6,
                bodyColor = { app.darkMode ? 0xC4CFD8 : 0x2E3B46 },
                codeBackground = { app.darkMode ? 0x35393F : 0xE9EFF4 },
                codeRule = { app.darkMode ? 0x37E0C8 : 0x12A08D },
                dark = { app.darkMode },
                text = { classroot.inlineDoc != "" ? classroot.inlineDoc : (classroot.src.value || "") } ]
            ]
        ]
    ]


/*
## JotWindow — a sticky note with its own chrome

A custom window type: square corners, yellow paper, and — when active — a
saturated title strip carrying olive-outlined pale widgets (a close box at the
left; a zoom triangle and a collapse box at the right). An inactive note is
chromeless: the strip and widgets vanish into the paper. It keeps all of the
base `Window`'s behavior — drag, the activation shadow, shade, resize edges —
through `chrome = false`, so here chrome is a skin, not the skeleton.
*/

class JotWindow extends Window [ width = 300, height = 250, chrome = false, forApp = "jots",
    baseRadius = 0, barH = 12, minW = 160, minH = 90,
    title = "",                                  // untitled — labels fall back to the app's name
    note: string = "",                           // the note's seed text

    // the note's palette: paper #FEF49C, active strip #FEEA3D, widget
    // linework #DBC501 dark olive over #FFF49C pale, and a half-pixel
    // #4E4E52 rim — a full CSS pixel reads as drawn-on lines, not an edge

    fill = #FEF49C,
    stroke = { stroke(0.5, 0x4E4E52) },
    inkHi = #00000052,
    inkLo = #00000038,
    shadow = { app.frontWin == this ? shadow(0, 10, 26, this.inkHi) : shadow(0, 3, 9, this.inkLo) },

    strip: View [ x = 0, y = 0, width = { parent.width }, height = { classroot.barH },
        fill = { classroot.active ? 0xFEEA3D : 0xFEF49C },
        onPointerDown() { classroot.beginDrag() },
        onPointerMove() { classroot.dragTo() },
        onPointerUp(e: PointerUpEvent)   { classroot.endDrag(e.canceled) },
        onHold() { classroot.activate() },   // the hold rider — same claim shape as the title bar; it also raises

        // the strip's widgets: dark olive outlines around pale interiors —
        // the close box 11px in from the left, the zoom triangle (right
        // angle at bottom-right) and the collapse box in from the right

        closeBox: View [ visible = { classroot.active }, x = 11, y = 2.25, width = 7.5, height = 7.5,
            fill = #FFF49C, stroke = { stroke(1.4, 0xDBC501) },
            onClick() { app.closeWin(classroot) }
            ],
        zoomW: View [ visible = { classroot.active }, x = { parent.width - 33 }, y = 2.25, width = 8, height = 8,
            onClick() { classroot.zoomToggle() },
            draw(d: Draw) {
                d.fillStyle = 0xFFF49C
                d.strokeStyle = 0xDBC501
                d.lineWidth = 1.4
                d.beginPath()
                d.moveTo(0.7, 7.3); d.lineTo(7.3, 7.3); d.lineTo(7.3, 0.7)
                d.closePath(); d.fill(); d.stroke()
                }
            ],
        collapseW: View [ visible = { classroot.active }, x = { parent.width - 21 }, y = 2.25, width = 8, height = 8,
            onClick() { classroot.shadeToggle() },   // collapse down to just the strip
            draw(d: Draw) {
                d.fillStyle = 0xFFF49C
                d.fillRect(0.7, 0.7, 6.6, 6.6)
                d.strokeStyle = 0xDBC501
                d.lineWidth = 1.4
                d.beginPath()
                d.rect(0.7, 0.7, 6.6, 6.6)
                d.stroke()
                d.beginPath()
                d.moveTo(0.7, 3.1); d.lineTo(7.3, 3.1)
                d.stroke()
                }
            ]
        ],

    // the note body is formatted — a Markdown field on the paper (no input
    // chrome, no focus ring; the note's text is authored, not typed)

    pad: View [ x = 12, y = { classroot.barH + 6 }, clip = true,
        width = { parent.width - 24 }, height = { parent.height - classroot.barH - 16 },
        md: Markdown [ width = { parent.width }, dark = false,
            bodyColor = 0x1D1D1F, scale = 0.82, lineHeight = 1.45,
            text = { classroot.note } ]
        ]
    ]


/*
## MiniTile — a minimized window's dock tile

An invisible click target that rides the same magnification swell as the
icons, so its hit area and label track the live thumbnail beneath it (the
thumbnail is the parked window itself). The tile sits in the dock layer above
the parked window, so a click restores it instead of poking its tiny content.
Its pill is the `DockIcon`'s, showing the window's title.
*/

class MiniTile extends View [

    // a static pool member (no replication, no Dataset): `ix` is assigned at
    // the use site, and every property below is a pure constraint over the
    // app's mini state — one atomic write to miniRecs re-derives the whole
    // tile, so no per-row machinery exists to go stale

    ix: number = 0,
    on: boolean = { app.miniRecs != null && this.ix < app.miniRecs.length },
    visible = { this.on },
    lbl: string = { this.on ? "" + app.miniRecs[this.ix].label : "" },
    kind: string = { this.on ? "" + app.miniRecs[this.ix].kind : "" },

    // geometry straight from the mini layout (the same entries the parked
    // window reads), translated into the minis section's local space

    slotW: number = { app.miniLayout != null && this.ix < app.miniLayout.length ? app.miniLayout[this.ix].w : 48 },
    slotH: number = { app.miniLayout != null && this.ix < app.miniLayout.length ? app.miniLayout[this.ix].h : 48 },
    slotRestW: number = { app.miniLayout != null && this.ix < app.miniLayout.length ? app.miniLayout[this.ix].rw : 48 },
    waveMag: number = { this.slotW / Math.max(1, this.slotRestW) },
    x = { (app.miniLayout != null && this.ix < app.miniLayout.length ? app.miniLayout[this.ix].x : 0) - (app.dock.x + app.dock.row.width + 32) },
    width = { this.slotW },
    height = { this.slotH },   // the thumbnail's aspect height (not icon-square), so the badge lands on the thumbnail's own corner
    y = { parent.height - 13.5 - 30.5 * this.waveMag - this.height / 2 },   // scales around the badge baseline (grows upward on rollover); at rest this is the plate center
    onClick() { app.restoreMiniAt(this.ix) },

    // the app-icon badge — on the tile (the dock layer, above the plate's
    // frost, so it renders crisp), gated by geometry: it shows exactly while
    // the window is seated in this slot — its visual width equals the slot's
    // (both sides derive from the same layout entry, so the equality holds
    // through the magnification wave, and never mid-journey: a traveling or
    // restored window's scale·width can't match). Pure derived fact — no
    // arrival bookkeeping at all.

    seated: boolean = { app.seatCheck(app.miniWins, this.ix, this.slotW, app.winSeq, app.pointerX, app.dock.hot) },

    // The badge is the app's own dock icon at badge scale — same class, same
    // art, so the calendar badge carries the live date.
    // Its wave/size/position constraints are displaced at this use site, and
    // its pointer handlers forward to the tile (so no second pill appears).

    badge: DockIcon [
        visible = { classroot.seated },
        width = { app.badgeEdge * classroot.waveMag }, height = { app.badgeEdge * classroot.waveMag },

        // x tracks the thumbnail's right edge (2px inside it); y sits on the
        // dock's common badge baseline (13.5px above the plate floor), not the
        // thumbnail's own bottom — so a short or landscape thumbnail's badge
        // hangs below it while a tall one stays contained. The tile's center is
        // the plate center; baseline = center + (44 - 13.5).

        x = { parent.width - (app.badgeEdge + 2) * classroot.waveMag },
        y = { parent.height / 2 + (30.5 - app.badgeEdge) * classroot.waveMag },
        kind = { classroot.kind == "calendar" ? "calendar" : classroot.kind == "jots" ? "jots" : classroot.kind == "files" ? "files" : classroot.kind == "birds" ? "bird" : "" },
        glyph = { classroot.kind == "markdown" ? "M↓" : classroot.kind == "declareviewer" ? "[  ]" : "" },
        hue1 = { classroot.kind == "markdown" ? 0x8E7CE8
            : classroot.kind == "declareviewer" ? 0x2E6FE0
            : classroot.kind == "calendar" ? 0xFFFFFF
            : classroot.kind == "birds" ? 0x66C95F
            : classroot.kind == "jots" ? 0xFCF4A7 : 0x59B0F6 },
        hue2 = { classroot.kind == "markdown" ? 0x5A46B8
            : classroot.kind == "declareviewer" ? 0x12A594
            : classroot.kind == "calendar" ? 0xEFEFF2
            : classroot.kind == "birds" ? 0x2C9243
            : classroot.kind == "jots" ? 0xF3E27E : 0x1D6FD1 },
        onClick() { app.restoreMiniAt(classroot.ix) }
        ],

    // the label pill — the DockIcon's, verbatim geometry: it floats just above
    // the tile's OWN top (local y), tail tip meeting it, so it rides the
    // magnified crest exactly as the app-icon pill does

    pill: View [ visible = { classroot.hovered },   // the TILE's hover, not the pill's:
        //  a pill hidden until hovered could never show itself (an invisible view
        //  is not on the hit chain), so the fact has to come from what it labels

        width = { this.t.width + 26 }, height = 33,
        x = center,
        y = { parent.height / 2 - 102 },   // pinned to the shared pill baseline (~62px above the plate top), same Y as the app-icon pills
        bodyH: number = 22,
        draw(d: Draw) { app.drawPill(d, this.width, this.bodyH, app.darkMode) },
        t: Text [ x = center, y = { (this.parent.bodyH - this.height) / 2 }, fontSize = 13,
            textColor = { app.darkMode ? 0xF2F2F5 : 0x1D1D1F },
            text = { classroot.lbl } ]
        ]
    ]


/*
## DockIcon — a drawn, labeled icon that magnifies by layout

Each icon's live width springs toward a target read from the pointer's distance
to its resting center, so hovering the dock swells the icons under the pointer
and displaces their neighbors. The magnification is layout, not paint: the
widths really change and the plate stretches to hold them.
*/

class DockIcon extends View [

    // per-icon inputs, fed at the use site

    ix: number = 0,                              // resting slot index
    slots: number = 10,                          // total icons — keep in step with the dock's row
    name: string = "",                           // the label pill's text
    hue1: Color = #4A90D9,                       // plate gradient, top → bottom
    hue2: Color = #2E5FA3,
    glyph: string = "",                          // a text glyph icon (⌘, ♪, …) …
    gsize: number = 0.42,                        //   … at this fraction of the plate (wide marks set less)
    kind: string = "",                           // … or drawn art: calendar | notes | mail | terminal | pencil | bird | jots
    running: boolean = false,

    // shared geometry — one place for the numbers the constraints below share

    rest: number = { app.iconEdge },             // resting icon size (the shared cell)
    pitch: number = { app.iconEdge + 16 },       // slot-center spacing: the resting size plus a 16px gap
    strip: number = 16,                          // the running-dot band below the icons

    // the face is rendered ONCE at this fixed reference size and paint-scaled to
    // the live magnified width (the plate's `scale` below). It must be ≥ the
    // largest magnified size (rest · 1.55 ≈ 87pt) so the transform only ever
    // DOWNsamples the hi-res raster — smooth, no shimmer — while the illustration
    // and rim draw()s invalidate only on real content change (calendar day,
    // theme), never per magnification frame. This keeps the wave inside Safari's
    // frame budget: 9 GPU blits, not 9 vector re-rasters, every frame.

    face: number = 96,

    // the resting slot center in app coords — the magnification's source must
    // not read the magnified layout (a feedback loop); resting geometry is
    // fixed: `pitch` about the app's center

    cx0: number = { app.width / 2 + (this.ix - (this.slots - 1) / 2) * this.pitch - app.miniSpan / 2 },

    // magnification: the shared wave (app.dockMag) about my resting center,
    // read off the SMOOTHED pointer (dockX) so it glides every frame, and
    // scaled by the enter/exit envelope (the dock's `hot`) so entering and
    // leaving glide too. Neighbors displace as the widths change — the wave
    // is layout, not paint.

    // Each icon springs its OWN magnification toward a target read from the raw
    // pointer, so every icon is always mid-flight during motion and the swell
    // glides continuously — smoother than a single shared spring, which would
    // settle between the browser's coalesced pointer events and step. The
    // resting center (cx0) feeds the distance, so the swell never reads its own
    // magnified output.

    // The dock's enter/exit gate, asked for rather than assumed. This class is
    // hosted in two places: the dock row, whose grandparent carries `hotGate`,
    // and a MiniTile, whose grandparent is the minis row and carries nothing.
    // In the second case the gate reads `undefined`, `1 + (w - 1) * undefined`
    // is NaN, and a spring can never arrive at NaN — so six of them chased it
    // for the life of the session. It cost no pixels (a badge takes its size
    // from its tile, not from `mag`) and no correctness, only a frame loop that
    // never parked. A host that states no gate is a host with no wave, which
    // is 0 — the value the arithmetic already produces for every icon the
    // pointer is nowhere near.

    gate(): number { const g = this.parent.parent.hotGate; return typeof g == "number" ? g : 0 },

    magTarget: number = { 1 + (app.dockMag(app.pointerX - this.cx0) - 1) * this.gate() },
    mag: number = 1,
    magSpring: Spring [ attribute = mag, to = { classroot.magTarget }, stiffness = 1300, damping = 62, epsilon = 0.002 ],
    width  = { this.rest * this.mag },
    height = { this.width },
    y = { parent.height - this.height - this.strip - this.hopY },   // bottom-anchored above the dot strip

    // The launch bounce: a ballistic arc — decelerating up, gravity down —
    // twice, about 560ms per bounce, poked by the app when an application first
    // opens (or first opens again after a Quit). The group cascades `attribute`
    // to its members; each leg is one half of the parabola.

    hopY: number = 0,

    bounce: AnimatorGroup [ attribute = hopY, process = sequential,
        Animator [ to = 30, duration = 300, motion = quadOut ],
        Animator [ to = 0, duration = 260, motion = quadIn ],
        Animator [ to = 30, duration = 300, motion = quadOut ],
        Animator [ to = 0, duration = 260, motion = quadIn ]
        ],

    poke() { this.bounce.start() },
    plate: View [ x = 0, y = 0, width = { classroot.face }, height = { classroot.face },
        // Paint-only magnification: the face is drawn once at `face`px and the
        // GPU scales it (about the top-left, so it fills the bottom-anchored box)
        // to the live width — no per-frame re-raster of the illustration or rim.
        // The DockIcon's LAYOUT width still grows, so neighbors displace as
        // before: the swell stays layout; only each icon's paint is cached.

        scale = { classroot.width / classroot.face },
        cornerRadius = { this.width * 0.23 }, clip = true,
        fill = { gradient(this.parent.hue1, this.parent.hue2) },

        // Glyph sizes stay fractional — rounding them would tick the art in
        // whole-pixel steps while the plate glides subpixel, a visible jitter.

        g: Text [ x = center, y = center, fontWeight = semibold, textColor = 0xFFFFFF,
            fontSize = { this.parent.width * classroot.gsize },
            visible = { classroot.glyph != "" },
            text = { classroot.glyph } ],

        // Drawn app art, authored in a 48-unit box and scaled to fill the plate.

        art: View [ x = 0, y = 0, width = { parent.width }, height = { parent.height },
            visible = { classroot.kind != "" },

            // the illustration is drawn at the icon's LIVE size — a canvas
            // scale inside draw() (vector, recomputed every frame) rather than
            // a CSS transform stretching a fixed 48px raster, which re-samples
            // and jitters a pixel as the magnification glides. The body keeps
            // its 48-unit authoring coordinates; only the scale moved inward.

            draw(d: Draw) {
                d.scale(this.width / 48, this.width / 48)
                const k = classroot.kind
                if (k == "calendar") {
                    d.fillStyle = 0xFFFFFF
                    d.fillRect(0, 0, 48, 48)
                    d.fillStyle = 0xFB4238
                    d.fillRect(0, 0, 48, 13)
                    // the weekday and day are drawn in the SAME 48-unit space,
                    // so the whole face — band, MON, and the number — scales as
                    // one unit at any size (dock crest or badge); no per-glyph
                    // font clamp to skew their relative sizes.
                    d.textAlign = "center"
                    d.fillStyle = 0xFFFFFF
                    d.font = "bold 7.5px system-ui, sans-serif"
                    d.textBaseline = "middle"
                    d.fillText(app.dayName, 24, 7)
                    d.fillStyle = 0x1D1D1F
                    d.font = "27px system-ui, sans-serif"
                    d.fillText("" + app.dayNum, 24, 31)
                    }
                else { app.drawKindArt(d, k, classroot.hue1) }
                }
            ],

        // the calendar's live weekday + day are drawn inside `art` (one 48-unit
        // face that scales whole), not as separate Text children

        // The icon's glossy edge — the same top-lit rim the dock plate carries,
        // scaled to the icon and drawn at its live size (no raster jitter as it
        // magnifies). A 1px white highlight, brightest along the top and fading
        // down, like the sheen a glossy rounded tile catches from above.

        rim: View [ x = 0, y = 0, width = { parent.width }, height = { parent.height },
            draw(d: Draw) {
                const w = this.width
                const h = this.height
                const r = w * 0.23
                const g = d.createLinearGradient(0, 0, 0, h)
                g.addColorStop(0, "rgba(255,255,255,0.42)")
                g.addColorStop(0.34, "rgba(255,255,255,0.07)")
                g.addColorStop(1, "rgba(255,255,255,0)")
                d.strokeStyle = g
                d.lineWidth = 1
                d.beginPath()
                d.roundRect(0.5, 0.5, w - 1, h - 1, r - 0.5)
                d.stroke()
                }
            ]
        ],

    // the running-app dot, centered in the strip below the icon

    // the dot marks is-running and never bounces: adding hopY back cancels the
    // icon's launch-bounce offset, pinning the dot to the strip. MEASURED from
    // the running dot: near-black on the light shelf, ~4px across — not muted
    // gray. theme.text IS that value (0x1D1D1F light) and flips to a light dot
    // under a dark theme, so it always reads against the shelf.

    dot: View [ width = 4, height = 4, cornerRadius = 2,
        x = { (parent.width - 4) / 2 }, y = { parent.height + 6 + this.parent.hopY },
        visible = { running }, fill = { theme.text } ],

    // The label pill — the dock's own tooltip: a frosted chip with a downward
    // pointer tick and no shadow. It floats just above the hovered icon's own
    // top, so its tail tip meets the icon and — since the hovered icon is the
    // swell's peak — it clears every neighbor. As the icon magnifies and its top
    // rises, the pill rides up with it.

    pill: View [ visible = { classroot.hovered },   // the ICON's hover, not the pill's
        width = { this.t.width + 26 }, height = 33,
        x = center,
        y = { parent.height - 130 },   // pinned to the shared pill baseline, so it lands right at any magnification
        bodyH: number = 22,
        draw(d: Draw) { app.drawPill(d, this.width, this.bodyH, app.darkMode) },
        t: Text [ x = center, y = { (this.parent.bodyH - this.height) / 2 }, fontSize = 13,
            textColor = { app.darkMode ? 0xF2F2F5 : 0x1D1D1F },
            text = { classroot.name } ]
        ]
    ]


/*
## App — the desktop root

The whole desktop: the wallpaper, the menu bar, the windows layer, and the
dock, plus the state and commands that tie them together. It tracks the browser
window with no size floor (a floor would make the page scroll, and a desktop
never scrolls), and the root clips, so a window hanging past an edge is cropped
where it lies rather than moved. Everything anchored to an edge — the menu bar's
width, the clock's right edge, the dock's seat at the bottom — re-derives from
app.width / app.height on every host resize.
*/

App [ appName = "Declare Desktop", scrolls = none,   // a fixed stage: overflow (wallpaper bleed, a window past the fold) is out of frame, never scroll range
    minWidth = 800, minHeight = 600,                 // the floors: in a smaller viewport the browser pans (and pinches) the held frame natively — frame-driven, not a scroll anyone declares
    theme = { Themes.cupertino(app.darkMode) },
    fontFamily = "system-ui, sans-serif",

    // a dark solid beneath the drawn wallpaper (the `wallpaper` view covers it;
    // this only shows before first paint / outside its bounds)

    fill = 0x0A0612,

    // Window-activation policy: a click on a background window only brings it
    // forward; the app inside hears nothing until the window is front. Flip to
    // false for click-through (the first click both activates and lands in the
    // content).

    firstClickActivatesOnly: boolean = true,

    // ── shared desktop geometry: named once, read by every constraint below ──

    menuBarH: number = 32,                       // the menu bar's height; windows live below it
    wallSeed: number = 7,                        // the generative wallpaper's seed; ` (backtick) cycles it

    // The tilt easter egg's seed (see Window.tilts): 0 = a level desktop
    // (boot state — the egg is dormant until pressed). `r` bumps it and every
    // window springs to a fresh random lean; `R` zeroes it and they all
    // spring level.

    tiltSeed: number = 0,
    scaleSeed: number = 0,                       // the zoom egg's seed; `s` re-rolls, `S` resets
    iconEdge: number = 56,                       // a dock icon's resting edge
    dockFloor: number = 13,                      // the icons' resting bottom line, up from the desktop's bottom edge
    badgeEdge: number = 20,                      // a minimized window's app badge, at rest
    thumbEdge: number = 64,                      // a minimized thumbnail's longer edge — bigger than an icon, and centered

    /*
    ### The dock's magnification swell

    The swell has two jobs, and each gets its own smoothing so the motion is
    FRAME-paced, not pointer-EVENT-paced (browsers coalesce pointer events and
    deliver them irregularly — a magnification read straight off `pointerX`
    stutters, holding for several frames and then jumping):

      • dockX — a spring that chases the raw pointer. Everything the swell
        touches reads dockX, so it re-derives every frame the spring ticks (the
        shared clock delivers those smoothly), gliding between the sparse
        pointer events. Its slight trail is the settle you feel.
      • hot — the enter/exit envelope (on the dock view): 0 when the pointer is
        away from the dock band, 1 while over it. It scales the whole swell, so
        entering and leaving glide instead of snapping.

    `dockMag` is the shape: distance-from-an-icon → magnification. The hovered
    icon reaches about 1.55× and the swell falls off over four icon-pitches as a
    pointed peak (a steep first step), set by the knots below. Distance is to
    the RESTING center (cx0), never the magnified layout, so the swell can't
    feed back on itself.
    */

    dockX: number = 0,

    // In-dock tracking: the swell sits under the cursor with about a frame of
    // lag and settles in ~110ms, critically damped (no tail).

    dockXSpring: Spring [ attribute = dockX, to = { app.pointerX }, stiffness = 1300, damping = 62, epsilon = 0.5 ],

    dockMag(dist: number) -> number {
        const pitch = this.iconEdge + 16
        const a = Math.abs(dist)
        const xs = [0, pitch, 2 * pitch, 3 * pitch, 4 * pitch]
        // A pointed peak, not a dome: the hovered icon reaches 1.55× and the
        // drop-off is steepest on the first step.
        // peak · ±1 · ±2 · ±3 · ±4 = 1.55 · 1.35 · 1.18 · 1.06 · 1.0.
        const ys = [1.55, 1.35, 1.18, 1.06, 1]
        if (a >= xs[4]) return 1
        for (let i = 0; i < 4; i++) {
            if (a <= xs[i + 1]) return ys[i] + (ys[i + 1] - ys[i]) * (a - xs[i]) / (xs[i + 1] - xs[i])
            }
        return 1
        },

    // an app illustration in the 48-unit authoring box (the caller has already
    // scaled to size, and painted the plate hue behind). The plate-hued `kind`s
    // only — the live calendar face is drawn by each caller, which owns the day
    // data. ONE renderer, shared by the dock icons and the "Not implemented"
    // alert, so an app's icon is identical wherever it appears.

    drawKindArt(d: Draw, kind: string, hue1: number) {
        if (kind == "files") {
            d.fillStyle = 0xD9E7FA
            d.beginPath()
            d.roundRect(9, 13.5, 14, 8, 2)
            d.fill()
            d.beginPath()
            d.roundRect(9, 16, 30, 19, 2.5)
            d.fill()
            d.fillStyle = 0xFFFFFF
            d.beginPath()
            d.roundRect(9, 20, 30, 15, 2.5)
            d.fill()
            }
        else if (kind == "mail") {
            d.fillStyle = 0xFFFFFF
            d.beginPath()
            d.moveTo(9, 15); d.lineTo(39, 15); d.lineTo(39, 34); d.lineTo(9, 34)
            d.closePath(); d.fill()
            d.strokeStyle = 0xB9C6DB
            d.lineWidth = 1.6
            d.beginPath()
            d.moveTo(9.5, 15.8); d.lineTo(24, 26); d.lineTo(38.5, 15.8)
            d.stroke()
            }
        else if (kind == "terminal") {
            d.strokeStyle = 0xFFFFFF
            d.lineWidth = 2.6
            d.lineCap = "round"
            d.beginPath()
            d.moveTo(14, 18.5); d.lineTo(20, 24); d.lineTo(14, 29.5)
            d.moveTo(24, 30); d.lineTo(32.5, 30)
            d.stroke()
            }
        else if (kind == "pencil") {
            // the pencil: eraser upper-left, tip lower-right. Body + tip in
            // white; the eraser seam struck back in the plate's hue.
            d.fillStyle = 0xFFFFFF
            d.beginPath()
            d.moveTo(7.8, 12.2); d.lineTo(14.2, 5.8); d.lineTo(35.7, 27.3); d.lineTo(29.3, 33.7)
            d.closePath(); d.fill()
            d.beginPath()
            d.moveTo(35.7, 27.3); d.lineTo(29.3, 33.7); d.lineTo(39.5, 37.5)
            d.closePath(); d.fill()
            d.strokeStyle = hue1
            d.lineWidth = 1.6
            d.beginPath()
            d.moveTo(11.4, 15.7); d.lineTo(17.7, 9.4)
            d.moveTo(13.5, 17.8); d.lineTo(19.8, 11.5)
            d.stroke()
            }
        else if (kind == "bird") {
            // the bird: a perched songbird facing right — one white
            // silhouette (beak, crown, back, tail, breast), with the eye and
            // the folded wing struck back in the plate's hue.
            d.fillStyle = 0xFFFFFF
            d.beginPath()
            d.moveTo(41.5, 16.5)                                     // beak tip
            d.lineTo(34.6, 13.4)                                     // beak base, top edge
            d.bezierCurveTo(33.2, 8.6, 26.4, 7.2, 22.8, 10.8)        // the crown
            d.bezierCurveTo(17.5, 15.8, 12.2, 25.4, 8.5, 37)         // the back, sloping to the tail
            d.lineTo(16.2, 34.2)                                     // the tail's notch
            d.bezierCurveTo(21.5, 36.6, 28.4, 36.4, 32.4, 32.2)      // the belly
            d.bezierCurveTo(35.6, 28.8, 36.2, 23.6, 34.9, 19.6)      // the breast, up to the throat
            d.closePath()                                            // throat back to the beak tip
            d.fill()
            d.fillStyle = hue1
            d.beginPath()
            d.arc(30.2, 14.6, 1.6, 0, Math.PI * 2)                   // the eye
            d.fill()
            d.strokeStyle = hue1
            d.lineWidth = 1.6
            d.lineCap = "round"
            d.beginPath()
            d.moveTo(24.5, 18.5)
            d.quadraticCurveTo(17.5, 22.5, 14.8, 30.5)               // the folded wing
            d.stroke()
            }
        else if (kind == "jots") {
            // all-yellow paper (the plate's yellow is the background), a
            // saturated strip and faint ruled lines
            d.fillStyle = 0xF3DC49
            d.fillRect(0, 0, 48, 10)
            d.strokeStyle = 0xE0CE66
            d.lineWidth = 2
            d.beginPath()
            d.moveTo(8, 19); d.lineTo(40, 19)
            d.moveTo(8, 27); d.lineTo(40, 27)
            d.moveTo(8, 35); d.lineTo(26, 35)
            d.stroke()
            }
        },

    // The label pill's silhouette — ONE path: a stadium body (fully-rounded
    // left/right ends, r = half the body height, so the caps are true
    // semicircles, not rounded-rectangle corners) plus a small fixed triangle
    // tail at bottom-center. Filled translucent and stroked as a single outline,
    // so the border wraps the tail with no seam. The body is ~22px, the tail
    // ~7px on a ~16px base, and the fill is ~0.88 so the wallpaper shows through.
    // The tail is fixed — it doesn't grow with the name.

    drawPill(d: Draw, w: number, bh: number, dark: boolean) {
        const r = bh / 2                     // stadium: fully-rounded ends (semicircle caps)
        const th = 7                         // FIXED triangle height — does NOT scale with the name
        const hb = 8                         // FIXED triangle half-base (narrow)
        const cx = w / 2
        d.beginPath()
        d.moveTo(r, 0)
        d.lineTo(w - r, 0)                                       // top edge
        d.arc(w - r, r, r, -Math.PI / 2, Math.PI / 2, false)    // right cap (semicircle)
        d.lineTo(cx + hb, bh)                                    // bottom edge → triangle base
        d.lineTo(cx, bh + th)                                    // down to the tip
        d.lineTo(cx - hb, bh)                                    // back up
        d.lineTo(r, bh)                                          // bottom edge
        d.arc(r, r, r, Math.PI / 2, Math.PI * 1.5, false)       // left cap (semicircle)
        d.closePath()
        d.fillStyle = dark ? "rgba(46,46,51,0.9)" : "rgba(242,242,246,0.88)"
        d.fill()
        d.strokeStyle = dark ? "rgba(0,0,0,0.35)" : "rgba(196,196,204,0.85)"
        d.lineWidth = 1
        d.stroke()
        },

    // Activation is one Window-typed slot: every window derives its look (shadow
    // depth, bar tone, controls) from whether it is this value.

    frontWin: Window = null,
    winCount: number = 0,                        // ever-opened count — staggers spawn positions
    viewerCount: number = 0,                     // open viewers, for the dock's running dot

    /*
    ### The application model

    Several "applications" share this desktop — Files, Markdown (the viewer),
    Declare Calendar and Declare Viewer (hosted apps), and Jots — and the
    menu bar is contextual: it belongs to the front window's application. A
    window's app is read from its class; About windows carry theirs explicitly.
    */

    pathOf(w: Window?) -> string { return w != null ? w.appPath : "" },

    appOf(w: Window?) -> string { return w != null && w.forApp != "" ? w.forApp : "files" },

    activeApp: string = { this.appOf(app.frontWin) },

    nameOf(a: string) -> string {
        return a == "markdown" ? "Markdown" : a == "calendar" ? "Declare Calendar"
            : a == "declareviewer" ? "Declare Viewer"
            : a == "birds" ? "50 Birds"
            : a == "jots" ? "Jots"
            : a == "desktop" ? "Declare Desktop" : "Files"
        },

    // View & Edit Source opens the running program itself in the Declare
    // Viewer — as an embedded app in a desktop window: the AppWindow hosts
    // apps/viewer, and `program=` in its env segment names the subject (a
    // path valid in this app's transport base). The viewer self-loads that
    // program's ?segments and ?file artifacts — reader mode by default.

    sourceRel(a: string) -> string {
        return a == "calendar" ? "../calendar/calendar.declare"
            : a == "declareviewer" ? "../viewer/viewer.declare"
            : a == "birds" ? "../birds/birds.declare"
            : "desktop.declare"
        },

    openSource(a: string) {
        this.openApp("declareviewer", "../../viewer/viewer", "Declare Viewer", null, "program=" + this.sourceRel(a))
        },

    // ── the command seam: the menu bar, the dock, and keys all route here ──

    command(id: string) {
        if (id == "new") {
            if (activeApp == "markdown") this.openViewer("../../docs/declare.md", "declare.md")
            else if (activeApp == "calendar") this.openApp("calendar", "../../calendar/calendar", "Calendar", null, "base=../calendar/")
            else if (activeApp == "declareviewer") this.openApp("declareviewer", "../../viewer/viewer", "Declare Viewer", null, "program=desktop.declare")
            else if (activeApp == "birds") this.openApp("birds", "../../birds/birds", "50 Birds", null, "base=../birds/")
            else if (activeApp == "jots") this.newJot("", null)
            else this.newFiles()
            }
        else if (id == "open") {
            if (activeApp == "declareviewer") this.openApp("declareviewer", "../../viewer/viewer", "Declare Viewer", null, "program=desktop.declare")
            else if (activeApp == "birds") this.openApp("birds", "../../birds/birds", "50 Birds", null, "base=../birds/")
            else if (activeApp == "jots") this.newJot("", null)
            else if (activeApp == "files" && frontWin != null) (frontWin as FilesWindow).openSelection()
            else this.openViewer("../../docs/declare.md", "declare.md")
            }
        else if (id == "close") { if (frontWin != null) this.closeWin(frontWin) }
        else if (id == "dark") { app.darkChoice = !app.darkMode; app.darkLocked = true }
        else if (id == "about-desktop") this.openAbout("desktop")
        else if (id == "about-app") this.openAbout(this.activeApp)
        else if (id == "source-desktop") this.openSource("desktop")
        else if (id == "home") app.navigate("apps/homepage/homepage.declare")   // distro-root-relative → works on dev server AND static host
        else if (id == "source") this.openSource(this.activeApp)
        else if (id == "quit") this.quitApp(this.activeApp)
        else if (id.indexOf("win:") == 0) this.focusWin(this.windows()[+id.slice(4)])
        },

    focusWin(w: Window?) { if (w == null) return; if (this.isMin(w)) this.restoreMini(w); else w.activate() },

    // Quit closes every window of that application — each by its own reverse
    // zoom — and clears its running flag (Files has no Quit; it's always
    // running). Running is an application state, not a window count: closing the
    // last window leaves the app running, its dock dot lit — only Quit ends it.

    quitApp(a: string) {
        const doomed = this.windows().filter((w) => this.appOf(w) == a)
        for (const w of doomed) this.closeWin(w)
        if (a == "markdown") mdRunning = false
        else if (a == "calendar") calRunning = false
        else if (a == "declareviewer") dvRunning = false
        else if (a == "birds") brdRunning = false
        else if (a == "jots") jotRunning = false
        },

    // A dock icon's click: a running app's icon raises its open windows (in
    // their stacking order, so the front one ends front); with none open —
    // running or not — the app's default open runs instead.

    /* A dock press dismisses an open menu AND does its own work — the dock rule,
       and worth stating because it is the opposite of a light dismiss. Clicking
       the wallpaper closes a menu and does nothing else; clicking the Dock closes
       it and opens the app, so the click is TAKEN, not swallowed.

       That is why the dock stays declared after `bar`: it paints above the menu's
       full-app backdrop, so the press reaches the dock rather than the catcher,
       and the dock closes the menu itself. `rootClose()` is what Escape uses —
       the whole chain, submenus included. Harmless when nothing is open.

       Every dock press routes through one of three verbs (dockOpen, notImpl,
       restoreMiniAt), so this sits at the top of each rather than on a wrapper
       view: events do not bubble, so a press on an icon never reaches the dock. */

    dockDismiss() { app.bar.mb.menu.rootClose() },

    dockOpen(a: string, open: () -> void) {
        this.dockDismiss()
        const live = this.windows().filter((w) => this.appOf(w) == a && !this.isPlain(w) && !this.isMin(w))
        if (live.length > 0) { for (const w of live) this.focusWin(w); return }
        // nothing up but something in the dock: restore the most recent tile
        const mins = this.miniList().filter((w) => this.appOf(w) == a)
        if (mins.length > 0) { this.restoreMini(mins[mins.length - 1]); return }
        open()
        },

    /*
    ### Minimize to dock

    A minimized window becomes a dock citizen: its geometry constraints run the
    icons' own swell math, so it magnifies and displaces along with the row, and
    the dock's span is sprung so the plate widens smoothly to admit it. The
    records here drive the invisible hit tiles and their label pills.
    */

    isMin(w: Window?) -> boolean { return w != null && w.dockSlot >= 0 },
    ixOf(w: Window?) -> number { return w != null ? w.dockSlot : -1 },
    labelFor(w: Window) -> string { const t = this.titleOf(w); return t != "" ? t : this.nameOf(this.appOf(w)) },

    // THE collection seam, and the one cast in the file: `wins` is populated at
    // runtime (createView), so its `children` is View[] — but every occupant is
    // a Window by construction (every open* path creates a Window subclass).
    // Typed HERE once, every window-taking method below can say `w: Window`.

    windows() -> Window[] { return this.wins.children as Window[] },
    miniList() -> Window[] { return this.windows().filter((w) => this.isMin(w)).sort((a, b) => this.ixOf(a) - this.ixOf(b)) },

    miniCount: number = 0,
    miniRecs: array = null,

    // compact the slot indices and rebuild the tile records — after every
    // park, unpark, and close-of-parked. Slot widths are per window: the
    // thumbnail keeps its window's aspect, its longer edge matching an app
    // icon's edge, so it is never wider or taller than an icon.

    // miniWins mirrors the records by index with the window references — a
    // parallel app attr, kept out of the records: records are data, and a
    // View's circular graph must never enter data-shaped state

    miniWins: Window[] = null,

    rebuildMinis() {
        const ws = this.miniList()
        const out = []
        let total = 0
        for (let i = 0; i < ws.length; i++) {
            ws[i].dockSlot = i
            // the longer edge matches an app icon's edge: a minimized
            // window is never wider or taller than an icon
            const fit = this.thumbEdge / Math.max(ws[i].width, ws[i].height)
            const slotW = Math.round(ws[i].width * fit)
            const slotH = Math.round(ws[i].height * fit)
            out.push(({ ix: i, label: this.labelFor(ws[i]), kind: this.appOf(ws[i]), w: slotW, h: slotH }))
            total += slotW + 8
            }
        miniRecs = out
        miniWins = ws
        miniCount = out.length
        // the mini section's resting width added to the plate: the divider zone
        // (34 = 16px left margin + line + 18px right) plus the slots and their
        // gaps. `total` already counts a trailing 8px gap, so: total + 34 − 8.
        miniGoal = out.length > 0 ? total + 26 : 0
        },

    // the minimized section's width — sprung toward the rebuilt goal, so
    // admitting or releasing a tile widens and narrows the dock as motion

    miniGoal: number = 0,
    miniSpan: number = 0,
    spanSpring: Spring [ attribute = miniSpan, to = { app.miniGoal }, stiffness = 380, damping = 34, epsilon = 0.5 ],

    // ── the mini layout: one computation both the parked windows and their
    // hit tiles read (deps arrive as arguments, so the constraint visibly
    // tracks them — the windowItems pattern). Left-anchored accumulation,
    // exactly like the icon row's layout: a magnified thumbnail pushes its
    // neighbors right and never crosses the divider on its left. The wave's
    // falloff runs over resting centers (the icons' anti-feedback rule).

    miniLayout: array = { this.computeMiniLayout(app.miniRecs, app.dockX, app.dock.hot,
        app.dock.x, app.dock.row.width, app.miniSpan, app.width) },

    // iconRow = the nine icons + eight gaps at rest; 10 = the plate's side
    // skirts (5 each); 5 = the row's inset in the plate; 17 = the divider
    // zone (8 + line + 8). The wave itself is app.dockMag — one curve, read
    // here for the tiles and by each DockIcon for the icons.

    computeMiniLayout(recs: array, px: number, hot: number, dockLeftX: number, rowW: number, span: number, appW: number) -> array {
        const rs = recs || []
        const iconRow = 9 * app.iconEdge + 8 * 16   // the nine icons + eight gaps, at rest
        // 32 = the plate's two 16px side skirts; 16 = the row's inset in the
        // plate; 34 = the divider zone (16px left margin + line + 18px right
        // margin) — the first thumbnail starts 34px past the last icon's edge
        const restDockX = (appW - (iconRow + 32 + span)) / 2
        let rx = restDockX + 16 + iconRow + 34      // first slot's resting left
        let lx = dockLeftX + 16 + rowW + 34         // …and its live left
        const out = []
        for (const r of rs) {
            const cx0 = rx + r.w / 2
            // the same wave the icons ride (app.dockMag), so tiles magnify in step
            const m = 1 + (app.dockMag(px - cx0) - 1) * hot
            const w = r.w * m
            out.push(({ x: lx, w: w, rw: r.w, h: (r.h || r.w) * m, cx: lx + w / 2 }))
            lx += w + 8
            rx += r.w + 8
            }
        return out
        },

    // the wave's extra width beyond rest — the plate stretches for it, so a
    // magnified thumbnail never hangs past the dock's right edge

    miniMagX: number = { this.magOf(app.miniLayout, app.miniRecs) },
    magOf(lay: array, recs: array) -> number {
        if (lay == null || recs == null || lay.length == 0) return 0
        let d = 0
        for (let i = 0; i < lay.length; i++) d += lay[i].w - recs[i].w
        return Math.max(0, d)
        },

    startPark(w: Window) { w.miniBack.stop(); w.bornX = 0; w.bornY = 0; w.miniGo.start() },
    startUnpark(w: Window) { w.miniGo.stop(); w.miniBack.start() },

    // settled-park state rides the records (the badge derives from its
    // record's `full`, plain data — no reactive aggregation in constraints):
    // full only after the arriving journey completes, and cleared the
    // instant the journey home begins

    minimizeWin(w: Window) {
        if (w == null || this.isPlain(w) || this.isMin(w)) return
        if (this.miniCount >= 6) return          // the static tile pool's size
        w.dockSlot = this.miniCount
        this.rebuildMinis()
        if (frontWin == w) frontWin = null
        w.raise()                                // the thumbnail pins to the top of the minimized band
        this.startPark(w)
        winSeq = winSeq + 1
        },

    bringFront(w: Window) { w.activate() },              // not focusWin — that would recurse via isMin

    // ── The minimized band: minimized windows' live thumbnails stay in `wins`
    // (below the plate) but pin to the TOP of the layer, so a full-size window
    // that reaches the dock can't cover them. A window that activates or opens
    // raises only to just BENEATH the band — `raise(below)` with the band's
    // floor — so the band always wins. `lowestMini` is that floor: the lowest-z
    // SETTLED minimized window (a homing or restoring window is leaving the
    // band, so it's excluded, and the restoring window comes up to the front of
    // the non-minimized band).

    lowestMini() -> Window? {
        const ws = this.windows()
        for (let i = 0; i < ws.length; i++) { const w = ws[i]; if (this.isMin(w) && !w.homing) return w }
        return null
        },

    // bring a freshly-opened window to the front of the NON-minimized band

    frontOpen(w: Window) { frontWin = w; w.raise(this.lowestMini()) },

    // seatedness for a tile's badge: the window's visual width equals the
    // slot's — geometry, not bookkeeping. Deps arrive as arguments (the
    // windowItems pattern); winSeq re-derives it at every journey boundary
    // (miniGo's completion nudges it), pointer/hot cover the wave frames.

    seatCheck(wins: Window[], i: number, slotW: number, seq: number, px: number, hot: number) -> boolean {
        const w = wins != null && i >= 0 && i < wins.length ? wins[i] : null
        if (w == null || w.homing == true) return false   // homing = leaving now: the badge goes first
        return w.scale < 0.9 && Math.abs(w.scale * w.width - slotW) < 0.5
        },

    nudge() { winSeq = winSeq + 1 },

    restoreMini(w: Window) {
        if (w == null || !this.isMin(w) || w.homing) return   // already on the way home
        w.homing = true
        this.startUnpark(w)                      // the slot stays mine until the journey home ends
        this.bringFront(w)                       // frontmost from the first frame of the journey
        winSeq = winSeq + 1
        },

    // miniBack's onStop: the window is home — release the slot and focus it

    unparked(w: Window) {
        w.dockSlot = -1
        w.homing = false
        this.rebuildMinis()
        this.focusWin(w)
        winSeq = winSeq + 1
        },

    restoreMiniAt(i: number) {
        this.dockDismiss()
        const ws = this.miniList()
        if (i >= 0 && i < ws.length) this.restoreMini(ws[i])
        },

    openAbout(a: string) {
        winCount = winCount + 1
        winSeq = winSeq + 1
        const w = this.wins.createView("AboutWindow", ({ forApp: "" + a,
            wx: (app.width - 280) / 2 + (winCount % 3) * 16, wy: 110 + (winCount % 3) * 14 }))
        this.frontOpen(w)
        },

    // a press that lands on nothing deeper (the wallpaper) also dismisses —
    // the App root is the sink of last resort

    dismissAbouts() {
        const doomed = this.windows().filter((w) => this.isPlain(w))
        for (const w of doomed) this.closeWin(w)
        },

    onPointerDown() { this.dismissAbouts() },

    // Appearance follows the OS color scheme (app.dark) by default; the menu's
    // Dark / Light item locks the choice to the user's pick from that point on,
    // so later system flips no longer move it.

    darkLocked: boolean = false,
    darkChoice: boolean = false,
    darkMode: boolean = { this.darkLocked ? this.darkChoice : app.dark },

    // ── The "Not implemented" alert: one app-modal sheet the inert dock apps
    // raise. A single slot of state — `notImpl` fills it (name + icon), and the
    // OK button clears it. `alertName == ""` means no alert.

    alertName: string = "",
    alertHead: string = "",                      // the terse per-app headline ("No." / "Nope." / …)
    alertKind: string = "",
    alertGlyph: string = "",
    alertGsize: number = 0.42,
    alertHue1: Color = #4A90D9,
    alertHue2: Color = #2E5FA3,
    notImpl(head: string, name: string, kind: string, glyph: string, gsize: number, h1: number, h2: number) {
        this.dockDismiss()
        alertHead = head
        alertName = name
        alertKind = kind
        alertGlyph = glyph
        alertGsize = gsize
        alertHue1 = h1
        alertHue2 = h2
        },
    dismissAlert() { alertName = "" },

    newFiles() {
        this.dismissAbouts()
        winCount = winCount + 1
        winSeq = winSeq + 1
        // spawn positions cascade, wrapping after a handful
        const w = this.wins.createView("FilesWindow", ({ wx: 90 + (winCount % 7) * 28, wy: 46 + (winCount % 7) * 26 }))
        this.frontOpen(w)
        },

    // Double-clicking a folder (or File → Open on one) opens a NEW Files window
    // drilled to that folder and PINNED so the folder's own column sits at the left
    // edge (its contents lead) — but the whole tree is present, so you can scroll
    // left all the way back to the root categories.

    openFolderWindow(folderPath: string, v: View?) {
        this.dismissAbouts()
        winCount = winCount + 1
        winSeq = winSeq + 1
        const depth = ("" + folderPath).split("\n").length - 1
        const w = this.wins.createView("FilesWindow", ({ wx: 90 + (winCount % 7) * 28, wy: 46 + (winCount % 7) * 26, selPath: "" + folderPath, focusDepth: depth }))
        this.frontOpen(w)
        },

    // Every open verb takes `v`, the view the open came from (the double-clicked
    // row or icon): the window zooms out of it and shrinks back to it on close.
    // With no origin (a menu, the dock, ⌘O) a window zooms gently from its own
    // center. originOf resolves that center in app coords by walking the parents.

    // ⚠ SCROLL OFFSETS COUNT. A row's `y` is its position in its column's
    // CONTENT, and the column scrolls — so summing the chain without subtracting
    // each scroller's offset gives where the row would be if nothing had ever
    // been scrolled. Scroll a file list halfway down and the window then zooms
    // out of a point off past the bottom of the screen.

    originOf(v: View?) -> object {
        if (v == null) return null
        let ox = v.width / 2
        let oy = v.height / 2
        let n = v
        while (n != null) {
            ox += n.x || 0
            oy += n.y || 0
            const p = n.parent
            if (p != null) { ox -= p.scrollX || 0; oy -= p.scrollY || 0 }
            n = p
            }
        return ({ x: ox, y: oy })
        },

    // A first open (count 0 — or 0 again after a Quit) is a launch: the dock
    // icon bounces and the window appears mid-second-bounce, the way a
    // fast-launching app feels. Later opens are instant.

    // ONE Markdown-window opener behind both verbs: `props` is what differs —
    // a `path` to fetch, or a hydrated `inlineDoc` + `docName` handed over
    // whole. Launch gating, spawn cascade, and the origin zoom are identical.

    openMarkdown(props: object, v: View?) {
        const first = !mdRunning && !mdLaunching
        if (first) mdLaunching = true
        const go = () => {
            mdLaunching = false
            mdRunning = true
            viewerCount = viewerCount + 1
            this.dismissAbouts()
            winCount = winCount + 1
            winSeq = winSeq + 1
            const wx = 160 + (winCount % 7) * 28
            const wy = 36 + (winCount % 7) * 26
            const o = this.originOf(v)
            const w = this.wins.createView("ViewerWindow", ({ ...props, wx: wx, wy: wy,
                bornX: o != null ? o.x - wx : -1, bornY: o != null ? o.y - wy - this.menuBarH : -1,
                bornFrom: v != null ? v : null }))
            this.frontOpen(w)
            }
        if (first) { this.dock.row.viewerIcon.poke(); setTimeout(go, 900) }
        else go()
        },

    openViewer(p: string, nm: string, v: View?) { if (p != "") this.openMarkdown(({ path: p }), v) },

    // …and a HYDRATED document — Markdown the model already assembled (an
    // element's reference, the enums page), handed over whole instead of fetched.

    openDoc(md: string, nm: string, v: View?) { if (md != "") this.openMarkdown(({ inlineDoc: md, docName: nm }), v) },

    // a full Declare app in a window — the path is demos/-relative (the slot
    // convention): "../../calendar/calendar" runs the real calendar,
    // "../../viewer/viewer" the Declare Viewer. `envExtra` appends to the
    // window's env segment ("program=…"). The two hosted apps count
    // separately (running dots + Quit are per application), and each has a
    // dock icon that launch-bounces on its first open.

    calCount: number = 0,
    dvCount: number = 0,
    brdCount: number = 0,

    // running is per application and survives its windows: set when a launch
    // completes, cleared only by Quit — the dock dots read exactly these

    mdRunning: boolean = false,
    calRunning: boolean = false,
    dvRunning: boolean = false,
    brdRunning: boolean = false,
    jotRunning: boolean = false,

    calLaunching: boolean = false,               // calendar mid-launch-bounce
    dvLaunching: boolean = false,                // Declare Viewer mid-launch-bounce
    brdLaunching: boolean = false,               // 50 Birds mid-launch-bounce
    mdLaunching: boolean = false,                // markdown mid-launch-bounce
    jotLaunching: boolean = false,                // Jots mid-launch-bounce

    // `a` is the APPLICATION KEY ("calendar" | "declareviewer" | "birds"),
    // passed rather than sniffed. It used to be derived from the path — `isCal =
    // p.indexOf("calendar") >= 0`, with "not the calendar" meaning the Declare
    // Viewer — which quietly hard-limited this to exactly two hosted apps and
    // would have made a third open under the second's name, dot and icon. The
    // key is also what `forApp` becomes, so `appOf`, Quit and the dock's
    // running dot all agree by construction.

    openApp(a: string, p: string, nm: string, v: View?, envExtra: string?) {
        const isCal = a == "calendar"
        const isBrd = a == "birds"
        // the launch gate: flags move inside go(), so the running dot appears
        // when the app has launched (mid-second-bounce), not at the click —
        // the mid-launch flag guards a double-click during the bounce
        const first = !(isCal ? calRunning : isBrd ? brdRunning : dvRunning)
                   && !(isCal ? calLaunching : isBrd ? brdLaunching : dvLaunching)
        if (first) { if (isCal) calLaunching = true; else if (isBrd) brdLaunching = true; else dvLaunching = true }
        const go = () => {
            if (isCal) { calLaunching = false; calRunning = true; calCount = calCount + 1 }
            else if (isBrd) { brdLaunching = false; brdRunning = true; brdCount = brdCount + 1 }
            else { dvLaunching = false; dvRunning = true; dvCount = dvCount + 1 }
            this.dismissAbouts()
            winCount = winCount + 1
            winSeq = winSeq + 1
            let wx = 110 + (winCount % 5) * 30
            let wy = 24 + (winCount % 5) * 22
            let ww = 880, wh = 560
            // The calendar opens smaller than a full app window and clears the
            // dock (its height caps to the room above it), centered
            // horizontally. The viewer keeps its base size.
            if (isCal) {
                wy = 28
                // clear the dock (height caps to the room above it) AND never
                // fall below the calendar's own min (480 × 420) — clamp to both.
                ww = Math.max(480, Math.min(920, this.width - 80))
                wh = Math.max(420, Math.min(600, this.height - this.menuBarH - wy - 168))   // 168 ≈ dock footprint + gap
                wx = Math.round((this.width - ww) / 2)
                }
            const o = this.originOf(v)
            const w = this.wins.createView("AppWindow", ({ appPath: "" + p, appTitle: "" + nm, forApp: a, wx: wx, wy: wy,
                width: ww, height: wh,
                extraEnv: envExtra != null ? envExtra : "",
                bornX: o != null ? o.x - wx : -1, bornY: o != null ? o.y - wy - this.menuBarH : -1,
                bornFrom: v != null ? v : null }))
            this.frontOpen(w)
            }
        if (first) { (isCal ? this.dock.row.calIcon : isBrd ? this.dock.row.brdIcon : this.dock.row.dvIcon).poke(); setTimeout(go, 900) }
        else go()
        },

    // ── Jots: the built-in application — its notes are JotWindows in
    // this very program, no island involved. The welcome note pre-opens at boot
    // (so Jots starts running, its dot lit, with no bounce — it was already
    // up when you arrived); later launches bounce like any app's.

    welcomeNote: string = """
**Hello!** This is a working desktop — windows, menus, a dock — running entirely in your browser.

It's built with **Declare**, a new language for user interfaces. A Declare program doesn't script behavior; it states what the interface *is* — this note's yellow, that window's shadow — and the runtime keeps every relationship true while you interact.

**Try things.** Drag the windows. Open apps from the dock. Minimize something. Browse the language's documentation in the Documentation window.

**Curious how it's made?** Press the `[ ]` icon in the dock to read this desktop's own source.

**Never, ever, press the 'r' or 's' keys.**
""",

    newJot(txt: string, v: View?) {
        const first = !jotRunning && !jotLaunching
        if (first) jotLaunching = true
        const go = () => {
            jotLaunching = false
            jotRunning = true
            this.dismissAbouts()
            winCount = winCount + 1
            winSeq = winSeq + 1
            const w = this.wins.createView("JotWindow", ({ note: "" + (txt || "*A new note.*"),
                wx: 480 + (winCount % 5) * 26, wy: 90 + (winCount % 5) * 24 }))
            this.frontOpen(w)
            }
        if (first) { this.dock.row.jotIcon.poke(); setTimeout(go, 900) }
        else go()
        },

    openWelcome() {
        jotRunning = true
        winSeq = winSeq + 1
        const w = this.wins.createView("JotWindow", ({ note: this.welcomeNote,
            width: 400, height: 385, wx: Math.max(440, app.width - 490), wy: 120 }))
        this.frontOpen(w)
        },

    closeWin(w: Window) { w.beginClose() },              // the reverse zoom; removal on its onStop

    reallyClose(w: Window) {
        winSeq = winSeq + 1
        // an About box carries its SUBJECT's forApp but is not a window OF that
        // app — `plain` is the discriminator, so closing "About Markdown" never
        // decrements the viewer count
        if (!w.plain) {
            if (w.forApp == "calendar") calCount = calCount - 1
            else if (w.forApp == "declareviewer") dvCount = dvCount - 1
            else if (w.forApp == "markdown") viewerCount = viewerCount - 1
            }
        if (frontWin == w) frontWin = null
        this.wins.removeChild(w)
        w.discard()
        this.rebuildMinis()                      // a Quit can take a minimized window's tile with it
        },

    // The menu-bar clock is live — a static time would be the first thing to
    // give the desktop away.

    clockText: string = "",

    dayName: string = "",
    dayNum: number = 0,

    tick() {
        const d = new Date()
        const wd = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"][d.getDay()]
        const mo = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][d.getMonth()]
        const h12 = d.getHours() % 12 == 0 ? 12 : d.getHours() % 12
        const mm = (d.getMinutes() < 10 ? "0" : "") + d.getMinutes()
        clockText = wd + " " + mo + " " + d.getDate() + "  " + h12 + ":" + mm + " " + (d.getHours() >= 12 ? "PM" : "AM")
        dayName = wd.toUpperCase()
        dayNum = d.getDate()
        },

    // ── The documentation model: one fetch of the docs app's own spine. The
    // Files browser's Guide and Reference folders, and the synthesized reference
    // pages, all derive from it.

    docsModel: DataSource [ url = "../../docs/declare-model.json" ],

    // 15s ticks catch the minute flip well within a minute-precision display

    // Both boot windows open one tick later: the welcome note's position
    // derives from app.width, which is not yet live inside onInit (the host
    // wires sizes after construction) — an immediate open would land on the
    // fallback floor. Order is deliberate: the note opens first, then the Files
    // window on top of it, so you arrive with Files frontmost and the greeting
    // resting behind.

    onInit() { this.docsModel.fetch(); setTimeout(() => { this.openWelcome(); this.newFiles() }, 0); this.tick(); setInterval(() => this.tick(), 15000) },

    // ── ⌘-shortcuts dispatch from the menus' own records: one registry, derived
    // from whatever the contextual bar currently shows, so the active
    // application's keys are automatically the live set — nothing is declared
    // twice.

    keyRegistry: array = { (app.menus || [])
        .flatMap((m) => (m.items || []).filter((r) => r.key).map((r) => ({ menu: "" + m.label, ...r }))) },

    keys: Keys [
        onKeyDown(e: KeyEvent) {
            if (e.key == "`" && !e.meta && !e.repeat) { app.wallSeed = app.wallSeed + 1; return }   // cycle the wallpaper (selection/debug)
            if (e.key == "r" && !e.meta && !e.repeat) { app.tiltSeed = app.tiltSeed + 1; return }   // the tilt egg: every window springs to a random lean
            if (e.key == "R" && !e.meta && !e.repeat) { app.tiltSeed = 0; return }                  // …and level again
            if (e.key == "s" && !e.meta && !e.repeat) { app.scaleSeed = app.scaleSeed + 1; return } // the zoom egg: every window springs to a random scale
            if (e.key == "S" && !e.meta && !e.repeat) { app.scaleSeed = 0; return }                 // …and true-size again
            if (!e.meta || e.repeat || e.key == "Meta") return
            if (app.bar.mb.shown) return             // an open menu owns the keyboard
            const combo = "⌘" + (e.key.length == 1 ? e.key.toUpperCase() : e.key)
            const hit = (app.keyRegistry || []).find((r) => r.key == combo && r.enabled != false)
            if (hit != null) app.command("" + hit.id)
            }
        ],

    /*
    ### The wallpaper — a generative mesh field, drawn

    A hue-tinted dark ground with five saturated color poles, biased to the edges
    and melted together with a big blur() under a `lighten` blend — a bold,
    cohesive gradient field. It is a PURE FUNCTION of `app.wallSeed`: a seeded
    PRNG picks the palette (a per-seed color scheme keeps hues cohesive rather
    than muddy) and the pole layout, so pressing ` (backtick) bumps the seed and
    rotates through the generated space. It has no handler, so a desktop press
    still dismisses an About box. Only draw()-subset primitives are used: radial
    gradients, filter blur(), and globalCompositeOperation — no images.

    **Drawn once, then paint-scaled.** The mesh is recorded in a FIXED reference
    box (refW × refH constants), so its display list never changes with the
    window — only `app.wallSeed` rebuilds it. On resize the view is cover-scaled
    to fill (uniform, aspect preserved: the tighter axis fits, the other overflows
    and clips) and re-centered, all with paint-only transforms, so the field never
    re-rasters on resize. This matters because WebKit's 2D canvas is deferred —
    draw() only records, and the raster flushes lazily — so re-recording this
    field every resize frame (five full-screen radial fills plus a blur) runs
    ~24ms per flush in Safari (~42fps), stalling the whole compositor so the dock
    trails the window; a cached raster plus a CSS scale is ~17ms (~60fps).
    (Chrome's GPU raster is eager — ~8ms either way — which is why the lag never
    showed there.) It's the same trick the dock icons use: draw once, then scale
    with a paint-only transform. 1920×1200 covers a common maximized window at
    scale ≤ 1 (crisp) and upscales gently past it (a blurred field hides the
    softness).
    */

    wallpaper: View [ refW: number = 1920,
        refH: number = 1200,
        width = { this.refW }, height = { this.refH },
        x = { (app.width - this.refW) / 2 }, y = { (app.height - this.refH) / 2 },
        pivotX = { this.refW / 2 }, pivotY = { this.refH / 2 },
        scale = { Math.max(app.width / this.refW, app.height / this.refH) },
        draw(d: Draw) {
            const W = this.width
            const H = this.height
            const hsl = (h, s, l) => "hsl(" + (((h % 360) + 360) % 360) + "," + s + "%," + l + "%)"
            // seeded PRNG (mulberry32) — deterministic per app.wallSeed
            let a = (app.wallSeed >>> 0) || 1
            const rnd = () => {
                a = (a + 1831565813) | 0                          // mulberry32's increment, in decimal (an 8-digit 0x here would read as a color)
                let t = Math.imul(a ^ (a >>> 15), 1 | a)
                t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
                return ((t ^ (t >>> 14)) >>> 0) / 4294967296
                }
            const hue0 = rnd() * 360
            // a COHESIVE color scheme per seed, so complementaries don't meet
            // and mud out; hue0 and the scheme swing strongly seed to seed
            const scheme = Math.floor(rnd() * 3)                 // 0 analogous · 1 triad · 2 split-complementary
            const hueFor = () => {
                if (scheme == 0) return hue0 + (rnd() - 0.5) * 100
                if (scheme == 1) return hue0 + [0, 120, 240][Math.floor(rnd() * 3)] + (rnd() - 0.5) * 26
                return rnd() < 0.72 ? hue0 + (rnd() - 0.5) * 74 : hue0 + 180 + (rnd() - 0.5) * 40
                }
            // dark, hue-tinted ground
            d.fillStyle = hsl(hue0, 52, 5)
            d.fillRect(0, 0, W, H)
            // five poles biased to the edges and corners, so the center never piles to white
            const spots = [[0.17, 0.24], [0.82, 0.2], [0.5, 0.54], [0.2, 0.82], [0.83, 0.8]]
            const blurPx = Math.round(Math.max(W, H) * 0.05)
            d.save()
            d.filter = "blur(" + blurPx + "px)"
            d.globalCompositeOperation = "lighten"                // per-channel max keeps overlaps saturated, not gray
            for (const s of spots) {
                const px = (s[0] + (rnd() - 0.5) * 0.18) * W
                const py = (s[1] + (rnd() - 0.5) * 0.18) * H
                const r = (0.36 + rnd() * 0.26) * Math.max(W, H)
                const h = hueFor()
                const sat = 70 + rnd() * 22
                const li = 44 + rnd() * 12
                const g = d.createRadialGradient(px, py, 0, px, py, r)
                g.addColorStop(0, hsl(h, sat, li))
                g.addColorStop(0.5, hsl(h, sat, li * 0.62))
                g.addColorStop(1, "rgba(0,0,0,0)")
                d.fillStyle = g
                d.fillRect(0, 0, W, H)
                }
            d.restore()
            // strong vignette — contrast, framing, and a darker center-out that
            // keeps the field from washing out
            const v = d.createRadialGradient(W / 2, H * 0.45, H * 0.1, W / 2, H * 0.5, W * 0.72)
            v.addColorStop(0, "rgba(0,0,0,0)")
            v.addColorStop(1, "rgba(0,0,6,0.62)")
            d.fillStyle = v
            d.fillRect(0, 0, W, H)
            // a faint top scrim so the (background-less) menu bar's light text
            // stays legible over any palette
            const top = d.createLinearGradient(0, 0, 0, 48)
            top.addColorStop(0, "rgba(0,0,0,0.30)")
            top.addColorStop(1, "rgba(0,0,0,0)")
            d.fillStyle = top
            d.fillRect(0, 0, W, 48)
            }
        ],

    // ── the windows layer: a structural container; order is promotion ──────

    wins: View [ x = 0, y = { app.menuBarH }, width = { app.width }, height = { app.height - app.menuBarH } ],

    winSeq: number = 0,                          // bumped on every open/close, so window lists re-derive

    /*
    ### The menu bar — whole menus as records, contextual

    The `menus` array re-derives from the active application (and from winSeq /
    frontWin for the Window menu), so the bar follows focus live, even while a
    menu is open. Keyboard shortcuts dispatch from these same records.
    */

    menus: array = { [
        ({ id: "brand", label: "Declare", kind: "BrandMark", items: [
            ({ id: "about-desktop", label: "About Declare Desktop", icon: "BracketIcon" }),
            ({ divider: true }),
            ({ id: "dark", label: app.darkMode ? "Light Mode" : "Dark Mode", key: "⌘K", icon: "AutoIcon" }),
            ({ divider: true }),
            ({ id: "source-desktop", label: "View & Edit Source", icon: "CodeIcon" }),
            ({ id: "home", label: "Declare Home" }),
        ] }),
        ({ id: "app", label: this.nameOf(this.activeApp), bold: true,
            items: this.appMenuItems(this.activeApp) }),
        ({ id: "file", label: "File", items: [
            ({ id: "new", label: "New", key: "⌘N" }),
            ({ id: "open", label: "Open…", key: "⌘O", enabled: this.activeApp != "calendar" }),
            ({ divider: true }),
            ({ id: "close", label: "Close Window", key: "⌘W", enabled: app.frontWin != null }),
        ] }),

        // the standard Edit suite — present and keyed, honestly disabled:
        // nothing on this desktop edits yet

        ({ id: "edit", label: "Edit", items: [
            ({ id: "undo", label: "Undo", key: "⌘Z", enabled: false }),
            ({ id: "redo", label: "Redo", key: "⇧⌘Z", enabled: false }),
            ({ divider: true }),
            ({ id: "cut", label: "Cut", key: "⌘X", enabled: false }),
            ({ id: "copy", label: "Copy", key: "⌘C", enabled: false }),
            ({ id: "paste", label: "Paste", key: "⌘V", enabled: false }),
            ({ divider: true }),
            ({ id: "selall", label: "Select All", key: "⌘A", enabled: false }),
        ] }),
        ({ id: "window", label: "Window", items: this.windowItems(this.winSeq, app.frontWin) }),
        ({ id: "help", label: "Help", items: [
            ({ id: "hsearch", kind: "HelpSearch" }),
            ({ id: "help-app", label: this.nameOf(this.activeApp) + " Help", icon: "LightbulbIcon" }),
        ] }),
    ] },

    // The application menu: About, View & Edit Source, and — except for Files,
    // which is always running — Quit.

    appMenuItems(a: string) -> array {
        const nm = this.nameOf(a)
        const out = []
        out.push(({ id: "about-app", label: "About " + nm }))
        out.push(({ divider: true }))
        out.push(({ id: "source", label: "View & Edit Source" }))
        if (a != "files") {
            out.push(({ divider: true }))
            out.push(({ id: "quit", label: "Quit " + nm, key: "⌘Q" }))
            }
        return out
        },

    // the Window menu is live state as records: the active application's open
    // windows, front one checked. `seq` and `front` arrive as arguments so
    // the menus constraint above visibly reads them — its re-derive hooks.

    isPlain(w: Window?) -> boolean { return w != null && w.plain },
    titleOf(w: Window?) -> string { return w != null ? w.title : "" },

    windowItems(seq: number, front: Window?) -> array {
        const a = this.activeApp
        const ws = this.windows()
        const out = []
        for (let i = 0; i < ws.length; i++) {
            if (this.isPlain(ws[i]) || this.appOf(ws[i]) != a) continue
            out.push(({ id: "win:" + i, label: this.titleOf(ws[i]) || this.nameOf(a), checked: ws[i] == front }))
            }
        if (out.length == 0) out.push(({ id: "nowin", label: "No Windows", enabled: false }))
        return out
        },

    // No background: the menu bar's words render straight on the wallpaper.
    // `ink` turns the titles light, and the wallpaper's top scrim keeps them
    // legible over any palette.

    bar: View [ x = 0, y = 0, width = { app.width }, height = { app.menuBarH },
        menuInk: Color = 0xF2F2F5,
        mb: MenuBar [ x = 10, height = { parent.height }, menus = { app.menus }, ink = { parent.menuInk },
            picked(id: string) { app.command(id) }
            ],
        clock: Text [ x = { parent.width - this.width - 14 }, y = center, fontSize = 13,
            fontWeight = medium,                 // 400 reads thin under browser antialiasing; medium holds up
            textColor = { parent.menuInk }, text = { app.clockText } ]
        ],

    /*
    ### The dock

    A translucent plate holding the icon row, the minimized-window tiles, and the
    magnification swell (see "The dock's magnification swell" above). Its width is
    the plate's, and it stays centered at the bottom of the screen.
    */

    dock: View [ height = 150,
        width = { this.plate.width },
        x = { (app.width - this.width) / 2 },
        y = { app.height - 155.5 },           // the 88px plate sits 5.5px off the bottom edge

        // The enter/exit envelope the icons scale by, sprung fast (~100ms), so
        // entry reads as one quick motion; inside the strip the icons track the
        // pointer directly. The band has hysteresis: it arms a fixed distance
        // above the bottom edge but, while hot, holds higher — past a magnified
        // icon's crest — so hovering the top of a grown icon doesn't fall out of
        // the band and collapse the dock under the pointer.
        //
        // `hovering` gates the whole band: when the pointer leaves the browser
        // window it clears, so the dock cools instead of staying magnified at
        // the pointer's last known column.

        armBand: number = 100,                   // the hover band arms this far above the bottom edge (~plate top at 93.5)…
        holdBand: number = 132,                  // …and holds to here while hot (past a magnified icon's crest ~104)
        hot: number = 0,

        // hotGate is the INSTANT band result (0/1). The app icons read it as
        // their wave gate, so their own per-icon mag springs do all the enter/
        // leave smoothing (no double-spring). `hot` is the SPRUNG version — the
        // mini section (a shared pointer-spring layout) still eases through it.

        hotGate: number = { app.hovering && app.pointerY > app.height - (this.hot > 0.5 ? this.holdBand : this.armBand) ? 1 : 0 },

        heat: Spring [ attribute = hot, to = { parent.hotGate }, stiffness = 3600, damping = 120, epsilon = 0.002 ],

        // at rest the icons sit clearly inside the plate; a magnified icon
        // crests above its top — bottom-anchored, top rises. The row must be
        // dock-height: the icons' bottom anchor reads parent.height, and a
        // shorter row would float them above the plate at rest.

        plate: View [ x = 0, y = { parent.height - 88 }, height = 88, width = { parent.row.width + 32 + app.miniSpan + app.miniMagX },
            cornerRadius = 27, fill = { app.darkMode ? 0x2A2A30 : 0xFCFCFE }, opacity = 0.4 ],

        // The plate's edge rim, DRAWN at full strength (the plate is translucent,
        // so the rim rides a sibling above it, not inside its opacity). A top-lit
        // inner highlight: a vertical white gradient stroke, brightest along the
        // TOP edge and fading down the sides to nothing at the floor — a "lit
        // from above" bevel. A faint outer hairline sets the plate off from the
        // wallpaper.

        plateRim: View [ x = 0, y = { parent.height - 88 }, height = 88, width = { parent.plate.width },
            draw(d: Draw) {
                const w = this.width
                const h = this.height
                const r = 27
                d.strokeStyle = app.darkMode ? "rgba(0,0,0,0.34)" : "rgba(112,124,148,0.22)"
                d.lineWidth = 1
                d.beginPath()
                d.roundRect(0.5, 0.5, w - 1, h - 1, r - 0.5)
                d.stroke()
                const g = d.createLinearGradient(0, 0, 0, h)
                g.addColorStop(0, app.darkMode ? "rgba(255,255,255,0.30)" : "rgba(255,255,255,0.62)")
                g.addColorStop(0.42, app.darkMode ? "rgba(255,255,255,0.05)" : "rgba(255,255,255,0.13)")
                g.addColorStop(1, "rgba(255,255,255,0)")
                d.strokeStyle = g
                d.lineWidth = 1.5
                d.beginPath()
                d.roundRect(1.4, 1.4, w - 2.8, h - 2.8, r - 1.4)
                d.stroke()
                }
            ],
        row: View [ x = 16, y = 0, height = { parent.height },
            layout: SimpleLayout [ axis = x, spacing = 16 ],

            // a running app's icon raises its open windows instead of opening
            // more — dockOpen: raise if any, else the app's default open
            // (which itself decides launch-bounce vs instant by the flag)

            DockIcon [ ix = 0, name = "Files", kind = "files", hue1 = #59B0F6, hue2 = #1D6FD1,
                running = true,
                onClick() { app.dockOpen("files", () => app.newFiles()) }
                ],
            viewerIcon: DockIcon [ ix = 1, name = "Markdown", glyph = "M↓", hue1 = #8E7CE8, hue2 = #5A46B8,
                running = { app.mdRunning },
                onClick() { app.dockOpen("markdown", () => app.openViewer("../../docs/declare.md", "declare.md")) }
                ],

            // the Declare Viewer as a dock application: launches (bounce, dot,
            // Quit) like the others, hosting the real apps/viewer as an
            // embedded app — opened, by default, on this program's own source

            dvIcon: DockIcon [ ix = 2, name = "Declare Viewer", glyph = "[  ]", gsize = 0.42,
                hue1 = #2E6FE0, hue2 = #12A594,   // the brand's blue→teal accent thread
                running = { app.dvRunning },
                onClick() { app.dockOpen("declareviewer", () => app.openApp("declareviewer", "../../viewer/viewer", "Declare Viewer", this, "program=desktop.declare")) }
                ],

            // A plausible set of applications — enough icons for the
            // magnification swell to read well.

            calIcon: DockIcon [ ix = 3, name = "Calendar", kind = "calendar", hue1 = #FFFFFF, hue2 = #EFEFF2,
                running = { app.calRunning },
                onClick() { app.dockOpen("calendar", () => app.openApp("calendar", "../../calendar/calendar", "Calendar", this, "base=../calendar/")) }
                ],
            jotIcon: DockIcon [ ix = 4, name = "Jots", kind = "jots", hue1 = #FCF4A7, hue2 = #F3E27E,
                running = { app.jotRunning },
                onClick() { app.dockOpen("jots", () => app.newJot("", this)) }
                ],

            // "50 Birds" — a hosted app: apps/birds, the Audubon field guide,
            // embedded in a desktop window exactly as Calendar and the Declare
            // Viewer are. One name everywhere: the dock pill, the window
            // title, and the application menu all read "50 Birds".

            brdIcon: DockIcon [ ix = 5, name = "50 Birds", kind = "bird", hue1 = #66C95F, hue2 = #2C9243,
                running = { app.brdRunning },
                onClick() { app.dockOpen("birds", () => app.openApp("birds", "../../birds/birds", "50 Birds", this, "base=../birds/")) }
                ],

            // "Write" — an inert placeholder (a pencil): its click shows the
            // "Not implemented" alert, like Mail and the others below.

            DockIcon [ ix = 6, name = "Write", kind = "pencil", hue1 = #F49B45, hue2 = #C96B1D,
                onClick() { app.notImpl("No.", "Write", "pencil", "", 0.42, 0xF49B45, 0xC96B1D) }
                ],
            DockIcon [ ix = 7, name = "Mail", kind = "mail", hue1 = #1E8CFB, hue2 = #1667D9,
                onClick() { app.notImpl("Nope.", "Mail", "mail", "", 0.42, 0x1E8CFB, 0x1667D9) }
                ],
            DockIcon [ ix = 8, name = "Music", glyph = "♪", gsize = 0.52, hue1 = #FB5C74, hue2 = #FA233B,
                onClick() { app.notImpl("Nah.", "Music", "", "♪", 0.52, 0xFB5C74, 0xFA233B) }
                ],
            DockIcon [ ix = 9, name = "Terminal", kind = "terminal", hue1 = #3A3A40, hue2 = #17171B,
                onClick() { app.notImpl("Not.", "Terminal", "terminal", "", 0.42, 0x3A3A40, 0x17171B) }
                ]
            ],

        // ── The minimized-window section: a vertical divider, then a hit tile
        // per minimized window — the visuals are the parked windows themselves,
        // riding the same swell. The section exists only while the sprung span
        // is open, and the divider fades in with the widening, so growth reads as
        // one motion with no seam.

        minis: View [ visible = { app.miniSpan > 0.5 },
            x = { parent.row.x + parent.row.width + 16 }, y = 0, height = { parent.height },
            div: View [ x = 0, y = { parent.height - 77 }, width = 1, height = 65,
                opacity = { Math.min(1, app.miniSpan / 26) },
                fill = { app.darkMode ? 0xFFFFFF48 : 0x00000042 } ],

            // a static pool of tiles, not replication: each is a pure
            // constraint reader over the app's mini state, positioned from
            // the shared layout — there is no per-row machinery to go stale

            rowM: View [ x = 0, y = 0, height = { parent.height },
                MiniTile [ ix = 0 ],
                MiniTile [ ix = 1 ],
                MiniTile [ ix = 2 ],
                MiniTile [ ix = 3 ],
                MiniTile [ ix = 4 ],
                MiniTile [ ix = 5 ]
                ]
            ]
        ],

    // ── The "Not implemented" alert: a translucent app-modal sheet — the scrim
    // swallows every press — sitting frontmost over all the chrome. Its icon
    // reuses the very renderer the dock draws (app.drawKindArt), badged with a
    // caution triangle.

    alert: View [ visible = { app.alertName != "" },
        x = 0, y = 0, width = { app.width }, height = { app.height },
        onPointerDown() { },                           // modal: presses on the scrim do nothing

        scrim: View [ x = 0, y = 0, width = { parent.width }, height = { parent.height }, fill = #00000026 ],

        panel: View [ width = 300, height = 422,
            // The panel sits slightly above center — the top gap is about a
            // third of the empty vertical space, never dead-center.

            x = center, y = { (parent.height - this.height) / 3 },
            cornerRadius = 20,
            fill = { theme.menuMaterial != null ? theme.menuMaterial : theme.surface },
            stroke = stroke(1, #FFFFFF80),
            shadow = shadow(0, 16, 50, #00000059),

            icon: AppGlyph [ x = 118, y = 26, edge = 64,
                kind = { app.alertKind }, glyph = { app.alertGlyph }, gsize = { app.alertGsize },
                hue1 = { app.alertHue1 }, hue2 = { app.alertHue2 } ],
            badge: CautionBadge [ x = 162, y = 70, edge = 30 ],

            title: Text [ x = center, y = 112, fontSize = 15, fontWeight = semibold,
                textColor = { theme.text }, text = { app.alertHead } ],
            msg: Text [ x = 20, y = 136, width = 260, wrap = true, textAlign = center,
                fontSize = 12, textColor = { theme.textMuted },
                text = { "Declare Desktop doesn't include " + app.alertName + "." } ],

            // The payoff — a rounded image with a thin hairline, so it reads as
            // deliberate rather than a stray asset.

            rick: Image [ source = "rick.jpeg", x = 22, y = 184, width = 256, height = 160,
                stretches = both, cornerRadius = 10, clip = true,
                stroke = { stroke(1, app.darkMode ? 0xFFFFFF2E : 0x0000002E) } ],

            ok: Button [ x = 16, y = { parent.height - 46 }, width = { parent.width - 32 },
                label = "OK", primary = true,
                onClick() { app.dismissAlert() }
                ]
            ]
        ]
    ]
